'use strict';

const guideFilename = 'Huong-dan-tinh-kiem-ke-khi-nha-kinh-Duyen-Hai-1.docx';

function guideDownloadButton() {
  return btn('Tải bản Word', 'download-guide', 'primary');
}

function inventoryGuide() {
  return "<div class=\"guide-layout\"><nav class=\"guide-contents\" aria-label=\"Mục lục hướng dẫn\"><h2>Mục lục</h2><a href=\"#huong-dan-chuong-1\" data-guide-target=\"huong-dan-chuong-1\"><span>1</span>Xác định kỳ kiểm kê và lập danh mục nguồn</a><a href=\"#huong-dan-chuong-2\" data-guide-target=\"huong-dan-chuong-2\"><span>2</span>Tính phát thải từ đốt nhiên liệu</a><a href=\"#huong-dan-chuong-3\" data-guide-target=\"huong-dan-chuong-3\"><span>3</span>Đổi nhiệt trị toàn phần sang nhiệt trị thực</a><a href=\"#huong-dan-chuong-4\" data-guide-target=\"huong-dan-chuong-4\"><span>4</span>Tính phát thải từ nước thải</a><a href=\"#huong-dan-chuong-5\" data-guide-target=\"huong-dan-chuong-5\"><span>5</span>Tính phát thải từ môi chất lạnh và chữa cháy</a><a href=\"#huong-dan-chuong-6\" data-guide-target=\"huong-dan-chuong-6\"><span>6</span>Tính phát thải từ bón đất và điện mua vào</a><a href=\"#huong-dan-chuong-7\" data-guide-target=\"huong-dan-chuong-7\"><span>7</span>Tính độ không đảm bảo chuẩn của đầu vào</a><a href=\"#huong-dan-chuong-8\" data-guide-target=\"huong-dan-chuong-8\"><span>8</span>Tổng hợp độ không đảm bảo và đầu vào dùng chung</a><a href=\"#huong-dan-chuong-9\" data-guide-target=\"huong-dan-chuong-9\"><span>9</span>Tổng hợp kiểm tra và xuất báo cáo</a><a href=\"#huong-dan-chuong-10\" data-guide-target=\"huong-dan-chuong-10\"><span>10</span>Tài liệu tra cứu và quy ước đối chiếu</a></nav><article class=\"guide-body\" aria-label=\"Nội dung hướng dẫn\"><p>Thực hành cho Nhà máy Nhiệt điện Duyên Hải 1 với GreenLedger</p><p>Tài liệu đi từ xác định ranh giới, thu chứng từ và chọn hệ số đến tính từng nguồn, tổng hợp phát thải, đánh giá độ không đảm bảo đo (ĐKĐBĐ) và xuất báo cáo. Các ví dụ dùng số liệu giả định và cấu hình mẫu AR6 của GreenLedger để bạn có thể tính lại từng bước.</p><section class=\"guide-chapter\" aria-labelledby=\"huong-dan-chuong-1\"><h2 id=\"huong-dan-chuong-1\" tabindex=\"-1\">1 Xác định kỳ kiểm kê và lập danh mục nguồn</h2><ol><li>Chốt năm và ranh giới. Ghi ngày bắt đầu, ngày kết thúc, các tổ máy và khu phụ trợ thuộc phạm vi, cùng cách xác định quyền kiểm soát. Đối chiếu danh mục thiết bị, sơ đồ công nghệ và hợp đồng trước khi khóa danh mục nguồn.</li><li>Gán mã cho từng nguồn. Dùng một dòng cho một tổ hợp thiết bị, nhiên liệu hoặc môi chất, hệ số và phương pháp đo. Khi đổi nhiên liệu, công nghệ hoặc hệ số giữa kỳ, tách dòng theo giai đoạn và ghi rõ thời gian.</li><li>Thu chứng từ theo tháng. Ghi số gốc, đơn vị, thiết bị đo, ngày, mã chứng từ và người kiểm tra. Phân biệt tháng thực sự bằng 0 với tháng còn thiếu số liệu. Đối soát tổng năm với báo cáo vận hành và kế toán.</li><li>Chốt thư viện hệ số. Lưu mã, đơn vị, nguồn, phiên bản, cận và mức phủ hoặc u chuẩn. Dùng hệ số phù hợp nhiên liệu, thiết bị, công nghệ và yêu cầu của kỳ báo cáo. Ghi bộ GWP‑100 dùng thống nhất trong kỳ.</li></ol><div class=\"table-wrap guide-table\" tabindex=\"0\" aria-label=\"Bảng số liệu minh họa\"><table><thead><tr><th scope=\"col\">Phạm vi</th><th scope=\"col\">Nhóm nguồn trong GreenLedger</th><th scope=\"col\">Chứng từ và dữ liệu đầu vào</th></tr></thead><tbody><tr><td>1</td><td>Đốt cố định và đốt di động</td><td>Than, dầu, khí, nhật ký tiêu thụ, phiếu cân, NCV, loại thiết bị hoặc xe.</td></tr><tr><td>1</td><td>Nước thải sinh hoạt và công nghiệp</td><td>Giờ công, BOD, công nghệ xử lý, lưu lượng, tổng N, COD, bùn và CH₄ thu hồi nếu có.</td></tr><tr><td>1</td><td>Môi chất lạnh và chữa cháy</td><td>Mã chất, khối lượng nạp bù, xả, thu hồi, biên bản bảo trì và sự cố.</td></tr><tr><td>1</td><td>Urê và vật liệu bón vôi vào đất</td><td>Khối lượng thực bón, loại vật liệu và nơi sử dụng.</td></tr><tr><td>2</td><td>Điện lưới mua vào</td><td>Chỉ số công tơ, hóa đơn kWh, hệ số lưới theo năm.</td></tr></tbody></table></div><p>Rà soát riêng các nguồn ngoài tám nhóm của app nếu thuộc ranh giới, ví dụ SF₆ ở thiết bị điện, nhiệt hoặc hơi mua vào, và phát thải quá trình từ hóa chất trong dây chuyền. Lập bảng tính bổ sung và ghi cách hợp nhất. Điện tự phát đã tính qua nhiên liệu đốt thuộc Phạm vi 1. Tách phần điện thực tế mua vào để lập Phạm vi 2.</p><p>Nguồn phương pháp và văn bản áp dụng được dẫn ở cuối tài liệu.</p></section><section class=\"guide-chapter\" aria-labelledby=\"huong-dan-chuong-2\"><h2 id=\"huong-dan-chuong-2\" tabindex=\"-1\">2 Tính phát thải từ đốt nhiên liệu</h2><p>Tính riêng cho mỗi loại nhiên liệu và mỗi khí. Nhiên liệu lò hơi, máy phát dự phòng là ví dụ nguồn cố định. Xe và máy cơ giới cần chọn hệ số phù hợp loại phương tiện, động cơ và nhiên liệu. NCV là nhiệt trị thực và EF là hệ số phát thải.</p><p class=\"guide-formula\">m (kg) = Lượng tiêu thụ × Hệ số quy đổi sang kg</p><p class=\"guide-formula\">m (Gg) = m (kg) ÷ 1.000.000</p><p class=\"guide-formula\">Q (TJ) = m (Gg) × NCV (TJ/Gg)</p><p class=\"guide-formula\">Khối lượng khí g (kg) = Q (TJ) × EF của khí g (kg/TJ)</p><p class=\"guide-formula\">E của khí g (tCO₂e) = Khối lượng khí g (kg) × GWP của khí g ÷ 1.000</p><p>Hệ số quy đổi sang kg bằng 1 nếu đã nhập theo kg, bằng 1.000 kg/tấn nếu nhập theo tấn, và bằng khối lượng riêng kg/lít nếu nhập theo lít. Chỉ quy đổi một lần. Với số liệu than có đối soát kho, lượng tiêu thụ bằng tồn đầu + nhập − xuất ngoài quá trình đốt − tồn cuối, có điều chỉnh theo nghiệp vụ đã xác minh. Dùng số liệu đo trực tiếp tại lò khi phù hợp và đối chiếu với kho.</p><h3>Ví dụ lò hơi dùng 50 000 lít dầu DO</h3><p>Dùng khối lượng riêng 0,84 kg/lít, NCV 43 TJ/Gg và EF lần lượt 74.100, 3 và 0,60 kg/TJ. Kết quả trung gian là 42.000 kg = 0,042 Gg và 1,806 TJ.</p><div class=\"table-wrap guide-table\" tabindex=\"0\" aria-label=\"Bảng số liệu minh họa\"><table><thead><tr><th scope=\"col\">Khí</th><th scope=\"col\">EF kg/TJ</th><th scope=\"col\">Khối lượng khí kg</th><th scope=\"col\">GWP‑100 ví dụ</th><th scope=\"col\">Phát thải tCO₂e</th></tr></thead><tbody><tr><td>CO₂</td><td>74.100</td><td>133.824,6000</td><td>1</td><td>133,824600</td></tr><tr><td>CH₄ hóa thạch</td><td>3</td><td>5,4180</td><td>29,8</td><td>0,161456</td></tr><tr><td>N₂O</td><td>0,60</td><td>1,0836</td><td>273</td><td>0,295823</td></tr><tr><td>Tổng</td><td></td><td></td><td></td><td>134,281879</td></tr></tbody></table></div><h3>Ví dụ xe đường bộ dùng 1 000 lít dầu DO</h3><p>Với cùng khối lượng riêng và NCV, nhiệt lượng là 0,03612 TJ. Dòng DO_ROAD trong bộ mẫu dùng EF 74.100, 3,90 và 3,90 kg/TJ. Phát thải từng khí lần lượt là 2,676492, 0,004198 và 0,038457 tCO₂e, tổng 2,719147 tCO₂e. Kiểm tra loại xe và đơn vị EF trước khi áp dụng. Nếu phương pháp dùng kg khí/km thì dùng quãng đường × EF, sau đó nhân GWP và chia 1.000.</p><p>Với sinh khối, ghi CO₂ sinh học ở chỉ tiêu báo cáo riêng theo phương pháp áp dụng. CH₄ và N₂O từ quá trình đốt vẫn được tính. Với nhiên liệu pha trộn, xác định tỷ phần hóa thạch và sinh học bằng dữ liệu phù hợp.</p><h3>Ví dụ lò đốt 1 000 tấn than á bitum</h3><p>Với NCV 18,9 TJ/Gg và EF mẫu 96.100, 10 và 1,5 kg/TJ, khối lượng là 1 Gg và nhiệt lượng là 18,9 TJ. CO₂, CH₄ và N₂O lần lượt đóng góp 1.816,2900, 5,6322 và 7,7396 tCO₂e, tổng 1.829,6618 tCO₂e. Khi dùng số liệu nhà máy, đối chiếu loại than và NCV của lô hoặc kỳ tương ứng.</p><p class=\"guide-source\"><a href=\"https://www.ipcc-nggip.iges.or.jp/public/2006gl/vol2.html\" target=\"_blank\" rel=\"noopener\">IPCC 2006 Quyển 2 Chương 2 và 3</a></p></section><section class=\"guide-chapter\" aria-labelledby=\"huong-dan-chuong-3\"><h2 id=\"huong-dan-chuong-3\" tabindex=\"-1\">3 Đổi nhiệt trị toàn phần sang nhiệt trị thực</h2><p>Dùng NCV đo hoặc NCV đã tính nếu có đủ hồ sơ. Khi chỉ có Qgross, xác định rõ cơ sở mẫu trên phiếu thử. Cơ sở nhận về ký hiệu ar, cơ sở khô ký hiệu d, cơ sở khô gió ký hiệu adb. NCV phải cùng cơ sở độ ẩm với khối lượng than dùng trong phép tính.</p><h3>IPCC 2006 Box 1 1</h3><p class=\"guide-formula\">Qnet,ar = Qgross,ar − 0,212 × H_ar − 0,0245 × M_ar − 0,008 × O_ar</p><p>Nhiệt trị tính bằng MJ/kg. H_ar, M_ar và O_ar lần lượt là phần trăm hydro, độ ẩm và oxy trên cơ sở nhận về, theo quy ước của phiếu phân tích. Nhập 10 cho 10%. Dùng Qgross và thành phần của cùng một mẫu.</p><h3>ISO 1928 công thức 18</h3><p class=\"guide-formula\">Qnet,p = [Qgross,V,d − 0,2122 × H_d − 0,0008 × (O_d + N_d)]</p><p class=\"guide-formula\">             × (1 − M/100) − 0,02443 × M</p><p>Qgross,V,d là nhiệt trị toàn phần ở thể tích không đổi trên cơ sở khô. H_d, O_d và N_d cũng ở cơ sở khô, theo phần trăm. M là độ ẩm của cơ sở muốn tính. Kết quả là NCV ở áp suất không đổi. Biểu thức trên dùng MJ/kg. Nếu phiếu ghi J/g hoặc kJ/kg, chia giá trị nhiệt trị cho 1.000 để được MJ/kg. 1 MJ/kg bằng 1 TJ/Gg.</p><p>Khi Qgross được đo trên mẫu khô gió có độ ẩm M_adb, có thể quy về cơ sở khô bằng Qgross,d = Qgross,adb ÷ (1 − M_adb/100) nếu hai giá trị dùng cùng định nghĩa nhiệt trị và chỉ đổi cơ sở ẩm. H, O, N lấy theo cơ sở và quy ước của phòng thử nghiệm.</p><h3>Đối chiếu hai phương pháp trên cùng mẫu</h3><p class=\"guide-formula\">f = 1 − M/100</p><p class=\"guide-formula\">Δ = f × (−0,0002 × H_d + 0,0072 × O_d − 0,0008 × N_d) + 0,00007 × M</p><p class=\"guide-formula\">Qnet ISO = Qnet IPCC + Δ     và     Qnet IPCC = Qnet ISO − Δ</p><p>Δ được suy ra từ hai biểu thức khi quy Qgross về cùng cơ sở và lấy H_ar = f × H_d, O_ar = f × O_d theo cùng quy ước thành phần. Nếu phòng thử nghiệm dùng quy ước khác về hydro hoặc oxy của nước, cần kiểm tra trước khi dùng phép đối chiếu.</p><p>Ví dụ dùng Qgross,d = 25 MJ/kg, H_d = 4%, O_d = 10%, N_d = 1% và M = 10%. Theo giả thiết trên, Qgross,ar = 22,5 MJ/kg, H_ar = 3,6% và O_ar = 9%. IPCC cho 21,419800 MJ/kg, ISO cho 21,483860 MJ/kg và Δ = 0,064060 MJ/kg.</p><p class=\"guide-source\"><a href=\"https://www.ipcc-nggip.iges.or.jp/public/2006gl/pdf/2_Volume2/V2_1_Ch1_Introduction.pdf#page=17\" target=\"_blank\" rel=\"noopener\">IPCC 2006 Box 1.1</a></p><p class=\"guide-source\"><a href=\"https://www.iso.org/standard/75883.html\" target=\"_blank\" rel=\"noopener\">ISO 1928:2020 của công thức trong ảnh</a></p><p class=\"guide-source\"><a href=\"https://www.iso.org/standard/86999.html\" target=\"_blank\" rel=\"noopener\">ISO 1928:2025</a></p></section><section class=\"guide-chapter\" aria-labelledby=\"huong-dan-chuong-4\"><h2 id=\"huong-dan-chuong-4\" tabindex=\"-1\">4 Tính phát thải từ nước thải</h2><h3>Nước thải sinh hoạt</h3><p>GreenLedger ước tính CH₄ theo giờ công, tải lượng BOD và công nghệ xử lý. BOD là nhu cầu oxy sinh hóa. B₀ là khả năng sinh CH₄ tối đa và MCF là hệ số hiệu chỉnh theo mức kỵ khí.</p><p class=\"guide-formula\">Người ngày quy đổi = Tổng giờ công ÷ 24</p><p class=\"guide-formula\">TOW (kg BOD) = Người ngày quy đổi × BOD (g/người/ngày) ÷ 1.000</p><p class=\"guide-formula\">EF_CH₄ = B₀ × MCF     và     CH₄ (kg) = TOW × EF_CH₄</p><p>Ví dụ 24.000 giờ công, BOD 40 g/người/ngày, B₀ = 0,60 kg CH₄/kg BOD và MCF = 0,50. TOW là 40 kg BOD, CH₄ là 12 kg, tương ứng 12 × 27 ÷ 1.000 = 0,3240 tCO₂e. Dùng tổng giờ công phản ánh số người thực tế và thời gian có mặt, kể cả lao động thuê ngoài nếu thuộc nguồn.</p><h3>Nước thải công nghiệp</h3><p>COD là nhu cầu oxy hóa học. Để tính CH₄, dùng lưu lượng và COD phù hợp với tải hữu cơ vào tuyến xử lý. Để tính N₂O phát sinh từ nước xả vào nguồn tiếp nhận, dùng lưu lượng xả và tổng N tại điểm xả. Cặp số liệu lưu lượng và nồng độ phải cùng vị trí và kỳ.</p><p class=\"guide-formula\">Tải COD (kg) = Σ [V vào (m³) × COD vào (kg/m³)]</p><p class=\"guide-formula\">CH₄ (kg) = Tải COD × B₀ × MCF</p><p class=\"guide-formula\">Tải N xả (kg N) = Σ [V xả (m³) × C tổng N (kg N/m³)]</p><p class=\"guide-formula\">N₂O (kg) = Tải N xả × EF (kg N₂O–N/kg N) × 44/28</p><p>Đổi nồng độ từ mg/L sang kg/m³ bằng cách chia 1.000. Khi có số liệu tháng, cộng tích lưu lượng × nồng độ từng tháng. Nồng độ dùng với tổng lưu lượng năm phải là trung bình gia quyền theo lưu lượng.</p><p>Ví dụ dùng cùng 1.000 m³ cho hai dòng lưu lượng minh họa, COD 100 mg/L, N 20 mg/L, B₀ = 0,25, MCF = 0,80 và EF N₂O–N minh họa = 0,005. Tải COD = 100 kg, CH₄ = 20 kg = 0,5400 tCO₂e. Tải N = 20 kg, N₂O = 0,157143 kg = 0,0429 tCO₂e. Tổng 0,5829 tCO₂e.</p><p>App có một lưu lượng trên mỗi dòng công nghiệp và công tắc tính CH₄. Nếu lưu lượng vào và xả khác nhau, lập hai phép tính theo đúng điểm đo và đối chiếu để tránh cộng trùng N₂O. Khi có bùn tách hoặc CH₄ thu hồi, phương trình IPCC cần xét các khoản đó theo phương pháp áp dụng. Rà soát riêng N₂O trong công đoạn xử lý, N₂O từ nước thải sinh hoạt và CH₄ từ nước xả nếu thuộc ranh giới. EF 0,005 trong ví dụ là cấu hình minh họa của app và cần xác nhận theo loại nước xả cùng tài liệu áp dụng.</p><p class=\"guide-source\"><a href=\"https://www.ipcc-nggip.iges.or.jp/public/2006gl/pdf/5_Volume5/V5_6_Ch6_Wastewater.pdf\" target=\"_blank\" rel=\"noopener\">IPCC 2006 Quyển 5 Chương 6</a></p><p class=\"guide-source\"><a href=\"https://www.ipcc-nggip.iges.or.jp/public/2019rf/pdf/5_Volume5/19R_V5_6_Ch06_Wastewater.pdf\" target=\"_blank\" rel=\"noopener\">IPCC 2019 Refinement Quyển 5 Chương 6</a></p></section><section class=\"guide-chapter\" aria-labelledby=\"huong-dan-chuong-5\"><h2 id=\"huong-dan-chuong-5\" tabindex=\"-1\">5 Tính phát thải từ môi chất lạnh và chữa cháy</h2><h3>Xác định lượng thoát ra trong kỳ</h3><p>Lập danh mục thiết bị lạnh và bình chữa cháy theo mã chất, khối lượng nạp danh định, ngày bảo dưỡng, lượng nạp bù, lượng thu hồi và sự cố. Dùng biên bản xác định lượng phát thải thực tế hoặc phương pháp cân bằng khối lượng phù hợp. Lượng nạp bù chỉ đại diện cho lượng rò rỉ khi hồ sơ cho thấy nó bù cho tổn thất trong kỳ. Nạp mới, điều chuyển hoặc thay thiết bị cần theo dõi riêng.</p><p class=\"guide-formula\">E (tCO₂e) = Khối lượng chất phát thải (kg) × GWP‑100 ÷ 1.000</p><p>Khi tính bằng cân bằng khối lượng cho một ranh giới, lượng phát thải bằng tồn đầu + lượng vào − tồn cuối − lượng ra có chứng từ. Tồn phải bao quát chất đang nằm trong thiết bị và bình dự trữ nếu cả hai cùng trong ranh giới. Xác minh khoản thu hồi, chuyển ra ngoài và xử lý để tránh khấu trừ hai lần.</p><h3>Môi chất hỗn hợp</h3><p class=\"guide-formula\">GWP_hỗn hợp = Σ (wᵢ × GWPᵢ)     với     Σ wᵢ = 1</p><p class=\"guide-formula\">u(GWP_hỗn hợp) = √[Σ (wᵢ × u(GWPᵢ))²]</p><p>wᵢ là tỷ lệ khối lượng dạng số thập phân. Công thức u giả định các thành phần GWP độc lập và tỷ lệ phối trộn cố định. Ví dụ 10 kg R‑410A, gồm 50% HFC‑32 và 50% HFC‑125. Với GWP lần lượt 771 và 3.740 trong bộ mẫu, GWP hỗn hợp = 2.255,5. Phát thải = 22,5550 tCO₂e.</p><p>Với u tuyệt đối của hai GWP là 146 và 286,18 trong bộ mẫu, u hỗn hợp = 160,6355, tương đương 7,1219% của GWP. Nếu chỉ xét thành phần này, u của dòng là 1,6064 tCO₂e. GreenLedger có chế độ đối chiếu Excel cũ bỏ trọng số trong phép tính u. Chọn chế độ có trọng số khi dùng phương trình trên.</p><h3>Chất chữa cháy</h3><p>Xác định lượng chất thực sự xả hoặc rò rỉ bằng biên bản sự cố và bảo trì. Ví dụ xả 50 kg CO₂ thì GWP = 1, phát thải = 0,0500 tCO₂e. GreenLedger đưa CO₂ chữa cháy vào cột CO₂. Với FM‑200 hoặc chất khác, dùng GWP theo đúng mã chất. Kiểm tra phạm vi báo cáo riêng với HCFC‑22 và các chất được quản lý theo chế độ khác.</p><p class=\"guide-source\"><a href=\"https://www.ipcc-nggip.iges.or.jp/public/2006gl/pdf/3_Volume3/V3_7_Ch7_ODS_Substitutes.pdf\" target=\"_blank\" rel=\"noopener\">IPCC 2006 Quyển 3 Chương 7</a></p><p class=\"guide-source\"><a href=\"https://www.ipcc.ch/report/ar6/wg1/chapter/chapter-7/\" target=\"_blank\" rel=\"noopener\">IPCC AR6 WGI Chương 7 và bảng bổ sung</a></p></section><section class=\"guide-chapter\" aria-labelledby=\"huong-dan-chuong-6\"><h2 id=\"huong-dan-chuong-6\" tabindex=\"-1\">6 Tính phát thải từ bón đất và điện mua vào</h2><h3>Urê đá vôi và dolomit bón vào đất</h3><p class=\"guide-formula\">E_CO₂ (tấn CO₂) = Khối lượng thực bón (tấn) × EF_C (tấn C/tấn) × 44/12</p><p>Hệ số Tier 1 minh họa theo IPCC là 0,20 cho urê, 0,12 cho đá vôi và 0,13 cho dolomit. Một tấn urê phát thải 0,7333 tấn CO₂, một tấn đá vôi phát thải 0,4400 tấn CO₂, và một tấn dolomit phát thải 0,4767 tấn CO₂. Tổng hợp theo lượng từng loại thực bón. Với hỗn hợp, tách lượng theo tỷ lệ khối lượng đã xác minh.</p><p>GreenLedger có hệ số mẫu cho urê và đá vôi trong nhóm bón đất. Tính riêng dolomit nếu cấu hình hiện tại chưa có lựa chọn phù hợp. Các hệ số bón đất này dành cho mục đích nêu trong chương IPCC. Nếu urê dùng trong SCR hoặc đá vôi dùng trong FGD, xác định riêng nguồn quá trình và phương pháp phù hợp dây chuyền. N₂O do bón đạm vào đất là phép tính riêng theo tải lượng N và hệ số N₂O–N.</p><h3>Điện lưới mua vào</h3><p class=\"guide-formula\">Điện mua (MWh) = Điện mua (kWh) ÷ 1.000</p><p class=\"guide-formula\">E điện (tCO₂e) = Điện mua (MWh) × EF lưới (tCO₂e/MWh)</p><p>Dùng chỉ số công tơ hoặc hóa đơn đã đối soát, có hệ số nhân công tơ nếu cần. Xác định phần điện thực mua trong ranh giới. Theo dõi điện tự sản xuất và điện xuất lưới riêng để tránh đếm hai lần. Chọn EF công bố phù hợp năm kiểm kê và lưu văn bản nguồn, đơn vị, năm áp dụng.</p><p>Ví dụ mua 1.000.000 kWh và dùng EF mẫu năm 2024 là 0,6187 tCO₂/MWh. Điện mua = 1.000 MWh, phát thải = 618,7000 tCO₂e. Giá trị này dùng để tái lập ví dụ trong GreenLedger. Trước khi dùng cho kỳ thực tế, đối chiếu văn bản công bố năm tương ứng.</p><p class=\"guide-formula\">u_rel,điện = √[u_rel,công tơ² + u_rel,EF²]     nếu hai đầu vào độc lập</p><p>Trong ví dụ app, u công tơ bằng 0,1% và độ lệch chuẩn mẫu của dãy EF 0,7221, 0,6766, 0,6592, 0,6187 bằng 0,0428307 tCO₂/MWh. Chia cho EF của năm ví dụ để có u tương đối khoảng 6,92%, rồi tổng hợp với u công tơ. App cho u = 42,8352 tCO₂e và U = 83,9570 tCO₂e với k = 1,96. Độ lệch chuẩn giữa các năm phản ánh biến động lịch sử, cần ghi rõ khi dùng làm giá trị thay thế cho u của hệ số năm.</p><p class=\"guide-source\"><a href=\"https://www.ipcc-nggip.iges.or.jp/public/2006gl/pdf/4_Volume4/V4_11_Ch11_N2O%26CO2.pdf\" target=\"_blank\" rel=\"noopener\">IPCC 2006 Quyển 4 Chương 11 phương trình 11.12 và 11.13</a></p></section><section class=\"guide-chapter\" aria-labelledby=\"huong-dan-chuong-7\"><h2 id=\"huong-dan-chuong-7\" tabindex=\"-1\">7 Tính độ không đảm bảo chuẩn của đầu vào</h2><p>Với từng nguồn, viết phương trình và lập bảng đầu vào gồm giá trị, đơn vị, chứng từ, kiểu đánh giá, phân bố hoặc mức phủ, k, u chuẩn và mã đầu vào dùng chung. Trong công thức, u_rel là tỷ lệ thập phân và u% = 100 × u_rel. Ô u số liệu hoạt động của GreenLedger nhập theo phần trăm, ví dụ nhập 0,2887 cho 0,2887%.</p><div class=\"table-wrap guide-table\" tabindex=\"0\" aria-label=\"Bảng số liệu minh họa\"><table><thead><tr><th scope=\"col\">Dữ liệu có sẵn</th><th scope=\"col\">Cách tính u chuẩn</th><th scope=\"col\">Điều kiện áp dụng</th></tr></thead><tbody><tr><td>n phép đo lặp kiểu A</td><td>s = √[Σ(xᵢ − x̄)²/(n − 1)]. u(x̄) = s/√n.</td><td>Đại lượng đầu vào là trung bình của các phép đo độc lập. Nếu dùng một phép đo đơn, s mô tả độ phân tán phép đo đơn.</td></tr><tr><td>Giấy chứng nhận hiệu chuẩn kiểu B</td><td>u = U_chứng nhận ÷ k_chứng nhận.</td><td>Dùng k và đơn vị trên giấy. Đổi về cùng cơ sở với số đọc dùng để tính.</td></tr><tr><td>Giới hạn sai số ±a kiểu B</td><td>u = a/√3.</td><td>Giả định phân bố chữ nhật trong khoảng ±a.</td></tr><tr><td>NCV hoặc EF có cận dưới L và cận trên H</td><td>GreenLedger dùng u = max(x − L, H − x)/2. Sau đó u_rel = u/abs(x).</td><td>Quy ước xấp xỉ của app. Với khoảng chuẩn đối xứng 95%, có thể dùng bán độ rộng/1,96. Khoảng rộng hoặc lệch mạnh cần xem lại mô hình.</td></tr><tr><td>GWP đã công bố kèm khoảng</td><td>u = bán độ rộng/k tương ứng, rồi chia cho GWP để ra u_rel.</td><td>Nếu khoảng giữa phân vị 5 và 95 và giả định gần chuẩn, k ≈ 1,645. Nếu nguồn đã cho một độ lệch chuẩn, dùng trực tiếp.</td></tr></tbody></table></div><p>Ví dụ trụ bơm có giới hạn ±0,5% cho u = 0,5%/√3 = 0,2887%. Với cân, nếu giới hạn là ±5 kg và tải cân thực là 5.000 kg, u_rel = 5/(√3 × 5.000), tức 0,0577%. Nếu tải thực hoặc dải hiệu chuẩn khác, tính theo dữ liệu áp dụng tại tải đó. Không cộng lặp cùng một ảnh hưởng đã nằm trong u của thiết bị.</p><p>Ví dụ NCV dầu DO 43 TJ/Gg với cận 41,4 và 43,3 cho u = 0,8 TJ/Gg và u_rel = 0,01860465, tức 1,8605%. Nếu NCV được tính từ Qgross, độ ẩm và thành phần hóa học, có thể truyền u qua công thức ở mục 3 bằng hệ số độ nhạy. Giữ cả tương quan giữa các đầu vào khi có căn cứ.</p><p>Bộ mẫu GreenLedger đang lưu u GWP CH₄ hóa thạch = 5,5. Nếu dùng biên ±11 cho khoảng 90% và giả định chuẩn, u suy ra khoảng 6,69. Ghi rõ cách quy đổi khi cập nhật thư viện và đối chiếu bộ GWP bắt buộc cho kỳ. Với u còn thiếu, ghi tình trạng thiếu và đánh giá ảnh hưởng. Một giá trị 0 trong cấu hình mẫu có thể là giả định tạm.</p><p class=\"guide-source\"><a href=\"https://www.bipm.org/documents/20126/2071204/JCGM_100_2008_E.pdf\" target=\"_blank\" rel=\"noopener\">JCGM 100:2008 mục 4 và phụ lục G</a></p></section><section class=\"guide-chapter\" aria-labelledby=\"huong-dan-chuong-8\"><h2 id=\"huong-dan-chuong-8\" tabindex=\"-1\">8 Tổng hợp độ không đảm bảo và đầu vào dùng chung</h2><h3>Cách GreenLedger hiện tính</h3><p class=\"guide-formula\">Với tích các đầu vào độc lập, u_rel(E) = √[Σ u_rel(xᵢ)²]</p><p class=\"guide-formula\">u(E) (tCO₂e) = |E| × u_rel(E)</p><p class=\"guide-formula\">Với tổng các kết quả độc lập, u_c = √[Σ u(Eᵢ)²]</p><p class=\"guide-formula\">U = k × u_c     và     U% = 100 × U/|E_tổng|</p><p>Với từng khí do đốt nhiên liệu, app gộp u của lượng dùng, NCV, EF và GWP bằng căn tổng bình phương. CO₂ có GWP = 1 theo định nghĩa. Với nước thải, các thành phần lần lượt theo tải lượng, nồng độ, hệ số và GWP của khí. Với bón đất, gộp lượng vật liệu và EF. Các hệ số đổi đơn vị và tỷ số phân tử lượng được xem là hằng số.</p><p>Sau khi tính u tuyệt đối của từng khí, GreenLedger tổng hợp theo dòng rồi theo toàn cơ sở với giả định độc lập. Hệ số phủ hiện tại là 1,96. Dưới giả định gần chuẩn, 1,96 tương ứng khoảng phủ 95% và k = 2 là cách làm tròn. Khi tổng phát thải bằng 0, tỷ lệ U% không xác định, nên báo cáo giá trị tuyệt đối và trạng thái dữ liệu.</p><div class=\"table-wrap guide-table\" tabindex=\"0\" aria-label=\"Bảng số liệu minh họa\"><table><thead><tr><th scope=\"col\">Dầu DO 50.000 lít</th><th scope=\"col\">CO₂</th><th scope=\"col\">CH₄</th><th scope=\"col\">N₂O</th></tr></thead><tbody><tr><td>E từng khí (tCO₂e)</td><td>133,824600</td><td>0,161456</td><td>0,295823</td></tr><tr><td>u tương đối theo app (%)</td><td>2,1375</td><td>118,1325</td><td>119,0863</td></tr><tr><td>u tuyệt đối (tCO₂e)</td><td>2,8606</td><td>0,1907</td><td>0,3523</td></tr></tbody></table></div><p>Căn tổng bình phương ba u tuyệt đối cho u_c = 2,8885 tCO₂e. Nhân 1,96 cho U = 5,6614 tCO₂e. Báo cáo 134,2819 ± 5,6614 tCO₂e, tương đương ±4,22% theo giả định hiện tại. Hai u tương đối rất lớn ở CH₄ và N₂O cho thấy giới hạn của xấp xỉ tuyến tính ở cấp từng khí.</p><h3>Tính đúng phần bất định dùng chung</h3><p>Xác định cùng một phép đo lượng nhiên liệu, cùng NCV của lô, cùng EF hoặc GWP, hay cùng sai lệch hiệu chuẩn trên nhiều dòng. Với mỗi đại lượng thực sự dùng chung, cộng các đóng góp có dấu theo hệ số độ nhạy rồi bình phương một lần. Ví dụ NCV của một dòng nhiên liệu tác động đồng thời đến các khí. Đóng góp u tuyệt đối từ NCV cho tổng dòng là |Σ E_khí| × u_rel(NCV).</p><p class=\"guide-formula\">cᵢ = ∂E/∂xᵢ     và     u_c² = Σ cᵢ²uᵢ² + 2Σ cᵢcⱼ cov(xᵢ,xⱼ), với i &lt; j</p><p>Khi tách một dòng thành hai dòng bằng nhau, phần bất định hoàn toàn dùng chung giữ nguyên theo tỷ lệ. Công thức độc lập trong app có thể làm phần này giảm theo √2. Dùng bảng rà soát đầu vào dùng chung để hiệu chỉnh bên ngoài khi cần. Với nguồn trọng yếu có bất định lớn, lệch mạnh hoặc nhiều tương quan, xem xét Approach 2 Monte Carlo theo IPCC.</p><p class=\"guide-source\"><a href=\"https://www.ipcc-nggip.iges.or.jp/public/2019rf/pdf/1_Volume1/19R_V1_Ch03_Uncertainties.pdf\" target=\"_blank\" rel=\"noopener\">IPCC 2019 Refinement Chương 3</a></p></section><section class=\"guide-chapter\" aria-labelledby=\"huong-dan-chuong-9\"><h2 id=\"huong-dan-chuong-9\" tabindex=\"-1\">9 Tổng hợp kiểm tra và xuất báo cáo</h2><p>Kỳ mẫu dùng các dòng dưới đây, với u lượng dùng 0,288675% cho hai dòng dầu DO và lưu lượng nước công nghiệp. u của nồng độ, cùng u số liệu hoạt động của các dòng khác, đặt bằng 0 trừ công tơ điện 0,1%. Các thành phần u của hệ số lấy từ bộ mẫu. Thay giả định bằng kết quả đánh giá phù hợp khi lập hồ sơ.</p><div class=\"table-wrap guide-table\" tabindex=\"0\" aria-label=\"Bảng số liệu minh họa\"><table><thead><tr><th scope=\"col\">Nguồn minh họa</th><th scope=\"col\">Phạm vi</th><th scope=\"col\">Phát thải tCO₂e</th><th scope=\"col\">u chuẩn tCO₂e</th></tr></thead><tbody><tr><td>Đốt cố định dầu DO</td><td>1</td><td>134,2819</td><td>2,8885</td></tr><tr><td>Xe đường bộ dùng dầu DO</td><td>1</td><td>2,7191</td><td>0,0704</td></tr><tr><td>Nước thải sinh hoạt</td><td>1</td><td>0,3240</td><td>0,0970</td></tr><tr><td>Nước thải công nghiệp</td><td>1</td><td>0,5829</td><td>0,1137</td></tr><tr><td>R‑410A</td><td>1</td><td>22,5550</td><td>1,6064</td></tr><tr><td>CO₂ chữa cháy</td><td>1</td><td>0,0500</td><td>0,0000</td></tr><tr><td>Urê và đá vôi bón đất</td><td>1</td><td>1,1733</td><td>0,0000</td></tr><tr><td>Điện lưới mua vào</td><td>2</td><td>618,7000</td><td>42,8352</td></tr><tr><td>Tổng</td><td>1 + 2</td><td>780,3863</td><td>42,9628</td></tr></tbody></table></div><p>Phạm vi 1 = 161,6863 tCO₂e. Phạm vi 2 = 618,7000 tCO₂e. Kết quả tổng theo giả định độc lập là 780,3863 ± 84,2071 tCO₂e với k = 1,96, tương đương ±10,79%. Cộng từ số chưa làm tròn. CO₂ sinh học và các nguồn được lập bảng riêng cần được đối chiếu theo ranh giới báo cáo.</p><h3>Trình tự thao tác trong GreenLedger</h3><ol><li>Tại Tổng quan, tạo hoặc chọn kỳ và cập nhật thông tin cơ sở. Kiểm tra năm, ranh giới và bộ GWP trước khi nhập.</li><li>Tại Thư viện hệ số, đối chiếu hệ số đang áp dụng và nguồn tài liệu. Trên web, dùng Quy đổi nhiệt trị để tính NCV nếu cần rồi đưa giá trị đã kiểm tra vào hệ số tương ứng.</li><li>Tại Dữ liệu hoạt động, chọn nhóm nguồn, hệ số và đơn vị. Nhập tổng năm hoặc số liệu 12 tháng. Lưu cùng mã chứng từ, thiết bị và u chuẩn tương đối.</li><li>Tại Tính toán &amp; ĐKĐBĐ, mở chi tiết từng nguồn và Phương pháp &amp; giả định. Đối chiếu đơn vị, tổng theo khí, u tuyệt đối và các đầu vào dùng chung.</li><li>Tại Báo cáo tổng hợp, xuất Excel và kiểm tra các trang Hoat dong, He so, Tinh toan, Tong hop và Ra soat DKBDB. So khớp tổng theo phạm vi với giao diện và bảng tính độc lập. Tải bản sao lưu JSON trong Sao lưu &amp; xuất dữ liệu.</li></ol><p>Trước khi phát hành, kiểm tra đủ tháng và nguồn, loại trùng, rà soát điểm đo, lưu phiên bản EF và GWP, và ghi rõ phương pháp cho mỗi nguồn bổ sung. Khi lập hồ sơ nộp, đối chiếu biểu mẫu và yêu cầu pháp lý áp dụng tại thời điểm nộp.</p></section><section class=\"guide-chapter\" aria-labelledby=\"huong-dan-chuong-10\"><h2 id=\"huong-dan-chuong-10\" tabindex=\"-1\">10 Tài liệu tra cứu và quy ước đối chiếu</h2><p>Hướng dẫn này tái lập các giá trị của bộ mẫu GreenLedger để kiểm tra phép tính. Chọn phiên bản hệ số và GWP theo quy định áp dụng cho hồ sơ. Khi đổi bộ hệ số hoặc GWP, ghi ngày thay đổi và đối chiếu lại các kỳ cần so sánh. Kiểm tra bản đính chính IPCC khi trích hệ số từ AR6.</p><h3>Nguồn phương pháp và hệ số</h3><p class=\"guide-source\"><a href=\"https://www.ipcc-nggip.iges.or.jp/public/2006gl/pdf/2_Volume2/V2_1_Ch1_Introduction.pdf\" target=\"_blank\" rel=\"noopener\">IPCC 2006 Quyển 2 Chương 1 và Bảng 1.2 về NCV</a></p><p class=\"guide-source\"><a href=\"https://www.ipcc-nggip.iges.or.jp/public/2006gl/pdf/2_Volume2/V2_2_Ch2_Stationary_Combustion.pdf\" target=\"_blank\" rel=\"noopener\">IPCC 2006 Quyển 2 Chương 2 về đốt cố định</a></p><p class=\"guide-source\"><a href=\"https://www.ipcc-nggip.iges.or.jp/public/2006gl/pdf/2_Volume2/V2_3_Ch3_Mobile_Combustion.pdf\" target=\"_blank\" rel=\"noopener\">IPCC 2006 Quyển 2 Chương 3 về đốt di động</a></p><p class=\"guide-source\"><a href=\"https://www.ipcc-nggip.iges.or.jp/public/2006gl/pdf/3_Volume3/V3_7_Ch7_ODS_Substitutes.pdf\" target=\"_blank\" rel=\"noopener\">IPCC 2006 Quyển 3 Chương 7 về môi chất và PCCC</a></p><p class=\"guide-source\"><a href=\"https://www.ipcc-nggip.iges.or.jp/public/2006gl/pdf/4_Volume4/V4_11_Ch11_N2O%26CO2.pdf\" target=\"_blank\" rel=\"noopener\">IPCC 2006 Quyển 4 Chương 11 về bón vôi và urê</a></p><p class=\"guide-source\"><a href=\"https://www.ipcc-nggip.iges.or.jp/public/2019rf/pdf/5_Volume5/19R_V5_6_Ch06_Wastewater.pdf\" target=\"_blank\" rel=\"noopener\">IPCC 2019 Refinement Quyển 5 Chương 6 về nước thải</a></p><p class=\"guide-source\"><a href=\"https://www.ipcc-nggip.iges.or.jp/public/2019rf/pdf/1_Volume1/19R_V1_Ch03_Uncertainties.pdf\" target=\"_blank\" rel=\"noopener\">IPCC 2019 Refinement Quyển 1 Chương 3 về độ không đảm bảo</a></p><p class=\"guide-source\"><a href=\"https://www.ipcc.ch/report/ar6/wg1/chapter/chapter-7/\" target=\"_blank\" rel=\"noopener\">IPCC AR6 WGI Chương 7 Bảng 7.15 và bảng bổ sung</a></p><p class=\"guide-source\"><a href=\"https://www.ipcc.ch/errata-citations/\" target=\"_blank\" rel=\"noopener\">IPCC danh mục đính chính</a></p><p class=\"guide-source\"><a href=\"https://www.bipm.org/documents/20126/2071204/JCGM_100_2008_E.pdf\" target=\"_blank\" rel=\"noopener\">JCGM 100:2008 về đánh giá và tổng hợp độ không đảm bảo đo</a></p><p class=\"guide-source\"><a href=\"https://www.iso.org/standard/86999.html\" target=\"_blank\" rel=\"noopener\">ISO 1928 về xác định nhiệt trị của than và cốc</a></p><h3>Văn bản đối chiếu tại Việt Nam</h3><p>Xem Thông tư 38/2023/TT-BCT cho ngành Công Thương và Nghị định 06/2022/NĐ-CP cùng các văn bản sửa đổi áp dụng theo kỳ và ngày nộp. Theo Cổng Thông tin điện tử Chính phủ, Nghị định 396/2026/NĐ-CP có hiệu lực từ 12/12/2026. Dùng bản Excel của app để đối chiếu số liệu với biểu mẫu đang áp dụng.</p><p class=\"guide-source\"><a href=\"https://vanban.chinhphu.vn/?docid=209514&amp;pageid=27160\" target=\"_blank\" rel=\"noopener\">Thông tư 38/2023/TT-BCT</a></p><p class=\"guide-source\"><a href=\"https://vanban.chinhphu.vn/?docid=213875&amp;pageid=27160\" target=\"_blank\" rel=\"noopener\">Nghị định 119/2025/NĐ-CP</a></p><p class=\"guide-source\"><a href=\"https://vanban.chinhphu.vn/?docid=220100&amp;pageid=27160\" target=\"_blank\" rel=\"noopener\">Nghị định 396/2026/NĐ-CP và chuỗi văn bản sửa đổi</a></p><p class=\"guide-source\"><a href=\"https://kiem-ke-knk-greenledger.khanhmai766.chatgpt.site/\" target=\"_blank\" rel=\"noopener\">Mở GreenLedger web</a></p></section></article></div>";
}

document.addEventListener('click', async event => {
  if (event.target.closest('[data-action="tab"][data-tab="7"]')) {
    requestAnimationFrame(() => window.scrollTo(0, 0));
  }
  const button = event.target.closest('[data-action="download-guide"]');
  if (button && !button.disabled) {
    button.disabled = true;
    try {
      const response = await fetch(guideFilename);
      if (!response.ok || response.redirected) throw new Error('Tệp hướng dẫn chưa sẵn sàng.');
      download(guideFilename, await response.arrayBuffer(), 'application/vnd.openxmlformats-officedocument.wordprocessingml.document');
    } catch {
      toast('Chưa tải được bản Word. Vui lòng thử lại.');
    } finally {
      button.disabled = false;
    }
    return;
  }
  const link = event.target.closest('[data-guide-target]');
  if (!link) return;
  const heading = document.getElementById(link.dataset.guideTarget);
  if (!heading) return;
  event.preventDefault();
  heading.focus({ preventScroll: true });
  heading.scrollIntoView({ block: 'start' });
});
